package net.civeira.phylax.features.oauth.authentication.domain.gateway;

import net.civeira.phylax.features.oauth.authentication.domain.AuthenticationData;
import net.civeira.phylax.features.oauth.authentication.domain.exception.AuthenticationException;

/**
 * Port for emitting authentication events.
 *
 * Responsibilities: - Notify successful login events. - Notify failed authentication attempts.
 *
 * Design notes: - Implemented by infrastructure event adapters. - Keeps event emission out of
 * domain logic.
 */
public interface EventNotifierGateway {

  /**
   * Publishes a successful login event.
   *
   * Used to trigger audit or monitoring hooks. Implementations may dispatch CDI or messaging
   * events.
   *
   * @param data authentication data
   */
  void loginOk(AuthenticationData data);

  /**
   * Publishes a failed login event.
   *
   * Used to trigger audit or monitoring hooks. Implementations may dispatch CDI or messaging
   * events.
   *
   * @param fail authentication exception
   */
  void loginFail(AuthenticationException fail);
}
